"use strict";const e=require("../common/http/request.js");exports.getPhoneInfo=function(){return e.get("getPhoneInfo")},exports.loginByEmail=function(n,o){return e.post(`loginEmail?email=${encodeURIComponent(n)}&code=${encodeURIComponent(o)}`)},exports.loginByPhone=function(n,o){return e.post(`loginPhone?phoneNumber=${encodeURIComponent(n)}&password=${encodeURIComponent(o)}`)},exports.sendEmailCode=function(n){return e.get("member/sendEmail",{email:n})};
